begin;
select plan(15);
select is((select count(*)::integer from public.meals where is_system and archived_at is null),7,'seven active predefined recipes');
select is((select count(*)::integer from public.meals where is_system and archived_at is not null),8,'eight old recipes retained but retired');
select is((select name from public.meals where app_id='meal-creamy-lemon-chicken'),'Creamy Lemon Chicken','recipe name');
select is((select servings::integer from public.meals where app_id='meal-creamy-lemon-chicken'),2,'two servings');
select is((select complexity from public.meals where app_id='meal-creamy-lemon-chicken'),'easy','manual complexity');
select is((select total_time_minutes from public.meals where app_id='meal-creamy-lemon-chicken'),30,'whole-recipe time');
select is((select image from public.meals where app_id='meal-creamy-lemon-chicken'),'{"kind":"asset","id":"creamy-lemon-chicken"}'::jsonb,'bundled generated image');
select is((select reference from public.meals where app_id='meal-creamy-lemon-chicken'),'https://www.tiktok.com/@madebythewa/video/7647909556240076033','source reference');
select is((select count(*)::integer from public.meal_ingredients i join public.meals m on m.row_id=i.meal_row_id where m.app_id='meal-creamy-lemon-chicken'),6,'six quantified ingredients');
select is((select round(sum(f.calories*i.servings)/max(m.servings))::integer from public.meal_ingredients i join public.meals m on m.row_id=i.meal_row_id join public.foods f on f.row_id=i.food_row_id where m.app_id='meal-creamy-lemon-chicken'),695,'per-serving calorie calculation matches client');
select ok((select nutrition_notes like '%unmeasured and excluded%' and nutrition_notes like '%Counts all chicken fat%' from public.meals where app_id='meal-creamy-lemon-chicken'),'uncertainty retained in Details');
select throws_ok($$update public.meals set image='{"kind":"asset","id":"../other"}' where app_id='meal-creamy-lemon-chicken'$$,'23514',null,'unknown asset denied at constraint');
select throws_ok($$update public.meals set image='{"kind":"url","url":"/arbitrary-relative.png"}' where app_id='meal-creamy-lemon-chicken'$$,'23514',null,'relative URLs remain denied');
select ok((select count(*)=14 from public.meal_ingredients i join public.meals m on m.row_id=i.meal_row_id where m.app_id in ('meal-yogurt-bowl','meal-pb-toast','meal-chicken-rice','meal-salmon-potato')),'old recipe ingredients unchanged');
select ok(not has_table_privilege('authenticated','public.meals','UPDATE'),'catalog direct writes remain denied');
select * from finish();
rollback;
